const cfg = $input.first().json;
const body = cfg.body;
const WARN = cfg.latencyWarnMs;
const CRIT = cfg.latencyCriticalMs;
const SEV = ['none', 'medium', 'high', 'critical'];

if (!Array.isArray(body) || body.length === 0) {
  return [{ json: { payloadOk: false, error: 'Body must be a non-empty JSON array of API results' } }];
}

const isNum = function (v) { return typeof v === 'number' && Number.isFinite(v); };
const found = new Map();
const rejected = [];
let healthy = 0;

body.forEach(function (e, index) {
  if (!e || typeof e.api_name !== 'string' || !e.api_name.trim()) {
    rejected.push({ index: index, reason: 'api_name missing' });
    return;
  }
  const issues = [];
  let level = 0;
  const add = function (type, lvl, detail) {
    issues.push({ type: type, detail: detail });
    level = Math.max(level, lvl);
  };

  const t = e.response_time_ms;
  if (!isNum(t) || t < 0) add('INVALID_DATA', 2, 'response_time_ms missing or invalid');
  else if (t > CRIT) add('HIGH_RESPONSE_TIME', 2, 'response time ' + t + ' ms');
  else if (t > WARN) add('HIGH_RESPONSE_TIME', 1, 'response time ' + t + ' ms');

  const s = e.status_code;
  if (!Number.isInteger(s) || s < 100 || s > 599) add('INVALID_DATA', 2, 'status_code missing or invalid');
  else if (s >= 500) add('REQUEST_FAILED', 3, 'HTTP status ' + s);
  else if (s >= 400) add('REQUEST_FAILED', 2, 'HTTP status ' + s);

  const r = e.records_returned;
  if (r === undefined || r === null) add('NO_RECORDS', 1, 'records_returned missing');
  else if (!isNum(r) || r < 0) add('INVALID_DATA', 2, 'records_returned invalid');
  else if (r === 0) add('NO_RECORDS', 1, 'zero records returned');

  if (issues.length === 0) { healthy++; return; }

  const apiName = e.api_name.trim();
  const types = Array.from(new Set(issues.map(function (i) { return i.type; }))).sort();
  const alertKey = apiName + '|' + types.join('+');
  found.set(alertKey, {
    alertKey: alertKey,
    apiName: apiName,
    issueTypes: types,
    issues: issues,
    severity: SEV[level],
    details: {
      responseTimeMs: t === undefined ? null : t,
      statusCode: s === undefined ? null : s,
      recordsReturned: r === undefined ? null : r
    }
  });
});

const alerts = Array.from(found.values());
return [{ json: {
  payloadOk: true,
  hasAnomalies: alerts.length > 0,
  alertKeys: alerts.map(function (a) { return a.alertKey; }),
  alerts: alerts,
  summary: { received: body.length, healthy: healthy, rejected: rejected.length, anomalies: alerts.length },
  rejected: rejected
} }];

const detected = $('Validate and Detect').first().json;
const existing = new Map();
$input.all().forEach(function (item) {
  if (item.json && item.json.alertKey) existing.set(item.json.alertKey, item.json);
});

const now = new Date().toISOString();
const out = [];
detected.alerts.forEach(function (a) {
  const old = existing.get(a.alertKey);
  if (old) {
    out.push({ json: Object.assign({}, a, {
      action: 'update',
      alertId: old.alertId,
      occurrences: (old.occurrences || 1) + 1,
      lastSeenAt: now
    }) });
  } else {
    const id = 'alt_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
    out.push({ json: Object.assign({}, a, {
      action: 'create',
      alertId: id,
      status: 'active',
      occurrences: 1,
      createdAt: now,
      lastSeenAt: now
    }) });
  }
});
return out;

const split = $('Split New vs Existing').all().map(function (i) { return i.json; });
const det = $('Validate and Detect').first().json;
const created = split.filter(function (a) { return a.action === 'create'; });
const updated = split.filter(function (a) { return a.action === 'update'; });
let aiMessages = 0;
let fallbackMessages = 0;
try {
  $('Generate Alert Message').all().forEach(function (i) {
    if (i.json.messageSource === 'ai') aiMessages++;
    else fallbackMessages++;
  });
} catch (e) {}
return [{ json: {
  status: 'ok',
  summary: det.summary,
  created: created.length,
  updated: updated.length,
  aiMessages: aiMessages,
  fallbackMessages: fallbackMessages,
  rejected: det.rejected,
  alerts: split.map(function (a) {
    return { alertId: a.alertId, apiName: a.apiName, severity: a.severity, action: a.action };
  })
} }];
